import{_ as s,c as a,o as i,ag as e}from"./chunks/framework.BeChtK_P.js";const g=JSON.parse('{"title":"SVG画圆之path","description":"","frontmatter":{"title":"SVG画圆之path","author":"welpher.yu","date":"2024-03-19T14:47:11.000Z","tags":["svg","path"],"categories":["web前端"]},"headers":[],"relativePath":"posts/2024/svg-path-draw-circle.md","filePath":"posts/2024/svg-path-draw-circle.md"}'),l={name:"posts/2024/svg-path-draw-circle.md"};function r(n,t,p,d,h,o){return i(),a("div",null,[...t[0]||(t[0]=[e(`<p>SVG中使用path画圆需要使用圆形命令。圆形path命令有两个：A和C。其中，A命令用于画整个圆形，而C命令则用于画圆的一部分。</p><p>以A命令为例，圆命令的语法为：A rx ry x-axis-rotation large-arc-flag sweep-flag x y。</p><table tabindex="0"><thead><tr><th style="text-align:center;"><div style="width:30px;"></div></th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;">名称</td><td>椭圆弧（elliptical Arc）</td></tr><tr><td style="text-align:center;">指令</td><td>A（绝对）a（相对）</td></tr><tr><td style="text-align:center;">参数</td><td>(rx ry x-axis-rotation large-arc-flag sweep-flag x y)+ <br> <code>rx</code>和<code>ry</code>是椭圆的两个半轴长度 <br> <code>x-axis-rotation</code>是椭圆相对于坐标系的旋转角度，角度数而非弧度数 <br> <code>large-arc-flag</code>是标记绘制大弧(1)还是小弧(0)部分 <br> <code>sweep-flag</code>是标记向顺时针(1)还是逆时针(0)方向绘制 <br> <code>x</code> <code>y</code> 是圆弧终点的坐标</td></tr><tr><td style="text-align:center;">描述</td><td>从当前点绘制一段椭圆弧到点 (x, y)，椭圆的大小和方向由 (rx, ry) 和 x-axis-rotation 参数决定， x-axis-rotation 参数表示椭圆整体相对于当前坐标系统的旋转角度。椭圆的中心坐标 (cx, cy) 会自动进行计算从而满足其它参数约束。large-arc-flag 和 sweep-flag 也被用于圆弧的计算与绘制。</td></tr></tbody></table><p>下面是一个绘制圆形的例子：</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">svg</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> width</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;100&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> viewBox</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-50 -50 100 100&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;path d=&quot;M0,-50</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">           A50,50 0 1,1 0,50</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">           A50,50 0 1,1 0,-50z&quot; fill=&quot;transparent&quot; stroke=&quot;#000&quot; stroke-width=&quot;2&quot;/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">svg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>其中M命令代表将起始点移动到(0,-50)，z命令代表闭合路径。 A命令画了两个半圆，分别从(0,-50)到(0,50)和从(0,50)到(0,-50)，组成了一个完整的圆形。</p><p>需要注意的是，在使用A命令画圆时，需要分别使用两个半圆来绘制完整的圆形。</p>`,7)])])}const k=s(l,[["render",r]]);export{g as __pageData,k as default};
